                  <!-- CTA overlay -->\n                    <div class=\"absolute inset-0 flex items-center justify-center\">\n                        <button class=\"custom-btn\" onclick=\"openModal('Know Complete Curriculum', 'Get Curriculum on WhatsApp')\">\n  Know Complete Curriculum\n</button>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</section>\n\n\n<section class=\"py-20 relative overflow-hidden\" style=\"background-color: #FAF8F4;\">\n    <div class=\"absolute inset-0 background-pattern\"></div>\n    <div class=\"absolute top-20 left-10 w-16 h-16 bg-white/20 rounded-full floating-animation hidden lg:block\"></div>\n    <div class=\"absolute bottom-10 right-20 w-20 h-20 bg-white/15 rounded-full floating-animation-delay hidden lg:block\"></div>\n    <div class=\"relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8\">\n        <div class=\"text-center mb-16 fade-in-up\">\n            <h2 class=\"text-3xl sm:text-4xl lg:text-5xl font-semibold mb-6\" style=\"color: #8F8166;\">\n                What Will You\n                <span class=\"authentic-text\">Gain?</span>\n            </h2>\n            <div class=\"w-24 h-1.5 mx-auto mb-6 bg-gradient-to-r from-red-500 to-red-600 rounded-full\"></div>\n            <p class=\"text-lg sm:text-xl text-gray-600 max-w-3xl mx-auto leading-relaxed\">\n                Transform your life with skills, confidence, and connections that last beyond the training\n            </p>\n        </div>\n\n        <div class=\"grid lg:grid-cols-2 gap-12 lg:gap-16 items-center\">\n            <!-- Left Column - Points -->\n            <div class=\"space-y-6\">\n                <!-- International Certification -->\n                <div class=\"flex items-start space-x-4 group\">\n                    <div class=\"w-10 h-10 bg-gradient-to-br from-red-100 to-red-200 rounded-full flex items-center justify-center flex-shrink-0 group-hover:scale-110 transition-transform duration-300\">\n                        <!-- Heroicon: academic-cap (outline) -->\n                        <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"w-5 h-5 text-red-600\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.75\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n                            <path d=\"M12 14l9-5-9-5-9 5 9 5z\"></path>\n                            <path d=\"M12 14l6.16-3.422\"></path>\n                            <path d=\"M12 14v6\"></path>\n                            <path d=\"M6 10.578V16\"></path>\n                        </svg>\n                        <span class=\"sr-only\">International certification</span>\n                    </div>\n                    <div>\n                        <h3 class=\"font-semibold text-lg mb-2\" style=\"color: #8F8166;\">International Certification</h3>\n                        <p class=\"text-gray-600 leading-relaxed\">Yoga Alliance accredited certificate recognized worldwide for teaching opportunities and career advancement.</p>\n                    </div>\n                </div>\n\n                <!-- Teaching Confidence -->\n                <div class=\"flex items-start space-x-4 group\">\n                    <div class=\"w-10 h-10 bg-gradient-to-br from-blue-100 to-blue-200 rounded-full flex items-center justify-center flex-shrink-0 group-hover:scale-110 transition-transform duration-300\">\n                        <!-- Heroicon: shield-check (outline-style stroke) -->\n                        <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"w-5 h-5 text-blue-600\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.75\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n                            <path d=\"M12 2l7 4v5c0 5-3.58 9.74-7 11-3.42-1.26-7-6-7-11V6l7-4z\"></path>\n                            <path d=\"M9 12l2 2 4-4\"></path>\n                        </svg>\n                        <span class=\"sr-only\">Teaching confidence</span>\n                    </div>\n                    <div>\n                        <h3 class=\"font-semibold text-lg mb-2\" style=\"color: #8F8166;\">Teaching Confidence</h3>\n                        <p class=\"text-gray-600 leading-relaxed\">Master the skills to lead safe, engaging classes with proper alignment, sequencing, and student guidance.</p>\n                    </div>\n                </div>\n\n                <!-- Personal Growth -->\n                <div class=\"flex items-start space-x-4 group\">\n                    <div class=\"w-10 h-10 bg-gradient-to-br from-green-100 to-green-200 rounded-full flex items-center justify-center flex-shrink-0 group-hover:scale-110 transition-transform duration-300\">\n                        <!-- Heroicon: sprout / leaf-outline (custom stroke) -->\n                        <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"w-5 h-5 text-green-600\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.75\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n                            <path d=\"M3 21s6-4 9-8c3-4 6-11 6-11s-7 3-11 6C7 10 3 21 3 21z\"></path>\n                            <path d=\"M14 6c1 1 2 2 2 4\"></path>\n                        </svg>\n                        <span class=\"sr-only\">Personal growth</span>\n                    </div>\n                    <div>\n                        <h3 class=\"font-semibold text-lg mb-2\" style=\"color: #8F8166;\">Personal Growth</h3>\n                        <p class=\"text-gray-600 leading-relaxed\">Develop a stronger body, calmer mind, and clearer sense of purpose through deep self-discovery.</p>\n                    </div>\n                </div>\n\n                <!-- Spiritual Connection -->\n                <div class=\"flex items-start space-x-4 group\">\n                    <div class=\"w-10 h-10 bg-gradient-to-br from-purple-100 to-purple-200 rounded-full flex items-center justify-center flex-shrink-0 group-hover:scale-110 transition-transform duration-300\">\n                        <!-- Heroicon: sparkles / lotus-ish stroke -->\n                        <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"w-5 h-5 text-purple-600\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.75\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n                            <path d=\"M12 2c2 3 4 4 6 6s2 3 2 3-4 1-8 1-8-1-8-1 0-1 2-3 4-3 6-6z\"></path>\n                            <path d=\"M12 22s2-4 4-6c2-2 4-2 4-2\"></path>\n                        </svg>\n                        <span class=\"sr-only\">Spiritual connection</span>\n                    </div>\n                    <div>\n                        <h3 class=\"font-semibold text-lg mb-2\" style=\"color: #8F8166;\">Spiritual Connection</h3>\n                        <p class=\"text-gray-600 leading-relaxed\">Gain tools for cultivating self-awareness, inner peace, and balanced living through ancient practices.</p>\n                    </div>\n                </div>\n\n                <!-- Global Community -->\n                <div class=\"flex items-start space-x-4 group\">\n                    <div class=\"w-10 h-10 bg-gradient-to-br from-orange-100 to-orange-200 rounded-full flex items-center justify-center flex-shrink-0 group-hover:scale-110 transition-transform duration-300\">\n                        <!-- Heroicon: globe-alt (outline) -->\n                        <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"w-5 h-5 text-orange-600\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.75\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n                            <circle cx=\"12\" cy=\"12\" r=\"10\"></circle>\n                            <path d=\"M2 12h20\"></path>\n                            <path d=\"M12 2c4 4 6 10 6 10s-2 6-6 10c-4-4-6-10-6-10s2-6 6-10z\"></path>\n                        </svg>\n                        <span class=\"sr-only\">Global community</span>\n                    </div>\n                    <div>\n                        <h3 class=\"font-semibold text-lg mb-2\" style=\"color: #8F8166;\">Global Community</h3>\n                        <p class=\"text-gray-600 leading-relaxed\">Build lifelong friendships with like-minded souls from around the world who share your journey.</p>\n                    </div>\n                </div>\n\n                <!-- Career Opportunities -->\n                <div class=\"flex items-start space-x-4 group\">\n                    <div class=\"w-10 h-10 bg-gradient-to-br from-teal-100 to-teal-200 rounded-full flex items-center justify-center flex-shrink-0 group-hover:scale-110 transition-transform duration-300\">\n                        <!-- Heroicon: rocket / briefcase hybrid stroke -->\n                        <svg xmlns=\"http://www.w3.org/2000/svg\" class=\"w-5 h-5 text-teal-600\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.75\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n                            <path d=\"M9 19l-2 2v-4\"></path>\n                            <path d=\"M22 11c0-5-4-9-9-9-1.2 0-2.4.2-3.5.6L2 11l6 6 3-1 3 1 6-6z\"></path>\n                        </svg>\n                        <span class=\"sr-only\">Career opportunities</span>\n                    </div>\n                    <div>\n                        <h3 class=\"font-semibold text-lg mb-2\" style=\"color: #8F8166;\">Career Opportunities</h3>\n                        <p class=\"text-gray-600 leading-relaxed\">Start teaching immediately or pursue advanced training with a solid foundation in authentic yoga.</p>\n                    </div>\n                </div>\n            </div>\n\n            <!-- Right Column - Image -->\n            <div class=\"relative\">\n                <div class=\"relative bg-white/20 backdrop-blur-sm rounded-3xl p-8 shado